describe("doctests of sympy.core.mul", () => {
  it("Mul(x, 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, 1))).toBe('x');
  });
  it("Mul(x, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, x))).toBe('x**2');
  });
  it("Mul(1, 2, evaluate=False)", () => {
    expect(sympyStr(new Mul([rational(1), rational(2)]))).toBe('1*2');
  });
  it("Mul(x, x, evaluate=False)", () => {
    const x = new Sym('x');
    expect(sympyStr(new Mul([x, x]))).toBe('x*x');
  });
  it("(-3*sqrt(2)*(2 - 2*sqrt(2))).as_content_primitive()", () => {
    const v1 = asContentPrimitive(mul(-3, pow(2, rational(1, 2)), add(2, mul(-2, pow(2, rational(1, 2))))), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(6, -sqrt(2)*(1 - sqrt(2)))');
  });
  it("(2*x*y*sin(x)*cos(x)).as_ordered_factors()", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr([rational(2), x, y, fn('sin', [x]), fn('cos', [x])])).toBe('[2, x, y, sin(x), cos(x)]');
  });
  it("(3*x*y).as_two_terms()", () => {
    const [x, y] = symbols('x y');
    const v1 = rational(3);
    expect(sympyStr([v1, at(asTwoTerms(mul(v1, x, y)), 1)], 't')).toBe('(3, x*y)');
  });
  it("2*(x + 1) # this is the 2-arg Mul behavior", () => {
    const x = new Sym('x');
    expect(sympyStr(rational(2).mul(add(1, x)))).toBe('2*x + 2');
  });
  it("y*(x + 1)*2", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(mul(y, add(1, x)).mul(rational(2)))).toBe('2*y*(x + 1)');
  });
  it("2*(x + 1)*y # 2-arg result will be obtained first", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(add(2, mul(2, x)).mul(y))).toBe('y*(2*x + 2)');
  });
  it("Mul(2, x + 1, y) # all 3 args simultaneously processed", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(mul(2, add(1, x), y))).toBe('2*y*(x + 1)');
  });
  it("2*((x + 1)*y) # parentheses can control this behavior", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(rational(2).mul(mul(y, add(1, x))))).toBe('2*y*(x + 1)');
  });
  it("a**3", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(pow(mul(x, pow(y, rational(1, 2))), rational(1, 2)).pow(3))).toBe('(x*sqrt(y))**(3/2)');
  });
  it("Mul(a,a,a)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(mul(pow(mul(x, pow(y, rational(1, 2))), rational(1, 2)), pow(mul(x, pow(y, rational(1, 2))), rational(1, 2)), pow(mul(x, pow(y, rational(1, 2))), rational(1, 2))))).toBe('(x*sqrt(y))**(3/2)');
  });
  it("a*a*a", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(mul(x, pow(y, rational(1, 2))).mul(pow(mul(x, pow(y, rational(1, 2))), rational(1, 2))))).toBe('x*sqrt(y)*sqrt(x*sqrt(y))');
  });
  it("a.args[0]", () => {
    expect(sympyStr(new Float({ man: 3n, exp: 1n }, 53))).toBe('6.00000000000000');
  });
  it("a.args[1]", () => {
    const x = new Sym('x');
    expect(sympyStr(x)).toBe('x');
  });
  it("m == uMul(sqrt(3), sqrt(2))", () => {
    expect(sympyStr(new Mul([pow(2, rational(1, 2)), pow(3, rational(1, 2))]).equals(new Mul([pow(2, rational(1, 2)), pow(3, rational(1, 2))])))).toBe('True');
  });
  it("m == uMul(u)", () => {
    expect(sympyStr(new Mul([pow(2, rational(1, 2)), pow(3, rational(1, 2))]).equals(new Mul([pow(2, rational(1, 2)), pow(3, rational(1, 2))])))).toBe('True');
  });
  it("m == Mul(*m.args)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("prod(range(3))", () => {
    expect(sympyStr(mul(1, 0, 1, 2))).toBe('0');
  });
  it("prod([S(2), 3])", () => {
    expect(sympyStr(mul(1, 2, 3))).toBe('6');
  });
  it("prod([1, 2], 3)", () => {
    expect(sympyStr(mul(3, 1, 2))).toBe('6');
  });
  it("expr", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(subs(mul(x, y), new Map([[y, new MatrixSymbol('A', rational(2), rational(2))]])))).toBe('x*A');
  });
});

describe("doctests of sympy.core.power", () => {
  it("p.as_base_exp()", () => {
    expect(sympyStr([Rational.of(2n), neg(new Pow(rational(1, 2), rational(2)).exp)], 't')).toBe('(2, -2)');
  });
  it("p.args", () => {
    expect(sympyStr([rational(1, 2), rational(2)], 't')).toBe('(1/2, 2)');
  });
  it("sqrt(4 + 4*sqrt(2)).as_content_primitive()", () => {
    const v1 = asContentPrimitive(pow(add(4, mul(4, pow(2, rational(1, 2)))), rational(1, 2)), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(2, sqrt(1 + sqrt(2)))');
  });
  it("sqrt(3 + 3*sqrt(2)).as_content_primitive()", () => {
    const v1 = asContentPrimitive(pow(add(3, mul(3, pow(2, rational(1, 2)))), rational(1, 2)), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(1, sqrt(3)*sqrt(1 + sqrt(2)))');
  });
  it("((2*x + 2)**2).as_content_primitive()", () => {
    const x = new Sym('x');
    const v1 = asContentPrimitive(pow(add(2, mul(2, x)), 2), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(4, (x + 1)**2)');
  });
  it("(4**((1 + y)/2)).as_content_primitive()", () => {
    const y = new Sym('y');
    const v1 = asContentPrimitive(pow(4, add(rational(1, 2), mul(rational(1, 2), y))), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(2, 4**(y/2))');
  });
  it("(3**((1 + y)/2)).as_content_primitive()", () => {
    const y = new Sym('y');
    const v1 = asContentPrimitive(pow(3, add(rational(1, 2), mul(rational(1, 2), y))), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(1, 3**((y + 1)/2))');
  });
  it("(3**((5 + y)/2)).as_content_primitive()", () => {
    const y = new Sym('y');
    const v1 = asContentPrimitive(pow(3, add(rational(5, 2), mul(rational(1, 2), y))), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(9, 3**((y + 1)/2))');
  });
  it("powsimp(eq) == eq", () => {
    const x = new Sym('x');
    expect(sympyStr(pow(3, add(2, mul(2, x))).equals(pow(3, add(2, mul(2, x)))))).toBe('True');
  });
  it("eq.as_content_primitive()", () => {
    const x = new Sym('x');
    const v1 = asContentPrimitive(pow(3, add(2, mul(2, x))), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(9, 3**(2*x))');
  });
  it("eq.as_content_primitive() (2)", () => {
    const [x, y] = symbols('x y');
    const v1 = asContentPrimitive(pow(add(2, mul(2, x)), y), { radical: false });
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(1, (2*(x + 1))**y)');
  });
});

